-- DEDUP (2026-08-11 verification): landing carries exact duplicate pairs.
-- Confirm query showed a SINGLE load run (1 distinct run id), so this is
-- single-load duplication, not appends; exact dups carry no information.
-- (This landing's metadata columns are INGESTED_AT/SOURCE_RUN_ID, no underscore.)
with source as (
    select * from {{ source('ripple_raw', 'FED_GOOGLE_POLADS_CREATIVE_ID_MAPPING') }}
